using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ShipmentServerService : IShipmentService
{
    private static readonly List<Shipment> _shipments = new()
    {
        new Shipment { Id = 1, TrackingNumber = "TRK-100001", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, CreatedAt = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(2), CustomerEmail = "alice@example.com", Description = "Electronics package" },
        new Shipment { Id = 2, TrackingNumber = "TRK-100002", Origin = "Chicago, IL", Destination = "Houston, TX", Status = ShipmentStatus.OutForDelivery, CreatedAt = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow, CustomerEmail = "bob@example.com", Description = "Furniture set" },
        new Shipment { Id = 3, TrackingNumber = "TRK-100003", Origin = "Seattle, WA", Destination = "Miami, FL", Status = ShipmentStatus.Pending, CreatedAt = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(5), CustomerEmail = "carol@example.com", Description = "Medical supplies" },
        new Shipment { Id = 4, TrackingNumber = "TRK-100004", Origin = "Denver, CO", Destination = "Boston, MA", Status = ShipmentStatus.Delivered, CreatedAt = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(-1), CustomerEmail = "alice@example.com", Description = "Office equipment" },
        new Shipment { Id = 5, TrackingNumber = "TRK-100005", Origin = "San Francisco, CA", Destination = "Phoenix, AZ", Status = ShipmentStatus.Delayed, CreatedAt = DateTime.UtcNow.AddDays(-4), EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "dave@example.com", Description = "Auto parts" },
    };

    private static int _nextId = 6;
    private static readonly Lock _lock = new();

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_shipments.ToList());
        }
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(s =>
                s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
            return Task.FromResult(shipment);
        }
    }

    public Task<List<Shipment>> GetShipmentsByCustomerAsync(string customerEmail)
    {
        lock (_lock)
        {
            var shipments = _shipments
                .Where(s => s.CustomerEmail.Equals(customerEmail, StringComparison.OrdinalIgnoreCase))
                .ToList();
            return Task.FromResult(shipments);
        }
    }

    public Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        lock (_lock)
        {
            shipment.Id = _nextId++;
            shipment.TrackingNumber = $"TRK-{100000 + shipment.Id}";
            shipment.CreatedAt = DateTime.UtcNow;
            _shipments.Add(shipment);
            return Task.FromResult(shipment);
        }
    }

    public Task<Shipment> UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(s => s.Id == id)
                ?? throw new InvalidOperationException($"Shipment {id} not found.");
            shipment.Status = status;
            return Task.FromResult(shipment);
        }
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments");

        group.MapGet("/", async (IShipmentService service) =>
            Results.Ok(await service.GetAllShipmentsAsync()))
            .RequireAuthorization();

        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, IShipmentService service) =>
        {
            var shipment = await service.GetShipmentByTrackingNumberAsync(trackingNumber);
            return shipment is not null ? Results.Ok(shipment) : Results.NotFound();
        }).RequireAuthorization();

        group.MapGet("/customer/{email}", async (string email, IShipmentService service) =>
            Results.Ok(await service.GetShipmentsByCustomerAsync(email)))
            .RequireAuthorization();

        group.MapPost("/", async (Shipment shipment, IShipmentService service) =>
        {
            var created = await service.CreateShipmentAsync(shipment);
            return Results.Created($"/api/shipments/track/{created.TrackingNumber}", created);
        }).RequireAuthorization();

        group.MapPut("/{id}/status", async (int id, ShipmentStatus status, IShipmentService service) =>
        {
            var updated = await service.UpdateShipmentStatusAsync(id, status);
            return Results.Ok(updated);
        }).RequireAuthorization();
    }
}

